const MATH_LESSON_BY_ID=new Map((typeof MATHS==='undefined'?[]:MATHS.lessons).map(x=>[x.id,x]));
const MATH_QUESTION_BY_ID=new Map((typeof MATHS==='undefined'?[]:MATHS.questions).map(x=>[x.id,x]));
let completionObserver=null,completionTimer=null;
const mathUI={topic:'all',kind:'all',status:'all',revealed:{},questionLimit:18,search:'',testReview:null};
function validateMaths(raw,allowActive=false){
 const m={level:raw?.level==='HL'?'HL':'SL',calculator:raw?.calculator==='nspire'?'nspire':'ti84',done:{},results:{},drafts:{},tests:[],activeTest:null};
 if(!raw||typeof raw!=='object')return m;
 for(const l of MATHS.lessons)if(raw.done?.[l.id]===true)m.done[l.id]=true;
 for(const q of MATHS.questions){const r=raw.results?.[q.id];if(r&&Number.isFinite(r.score)&&r.score>=0&&r.score<=q.marks){m.results[q.id]={score:r.score,at:Number(r.at)||Date.now()};if(Number.isInteger(r.choice)&&r.choice>=0&&r.choice<q.options?.length)m.results[q.id].choice=r.choice;if(typeof r.value==='string')m.results[q.id].value=r.value.slice(0,100);}if(typeof raw.drafts?.[q.id]==='string')m.drafts[q.id]=raw.drafts[q.id].slice(0,8000);}
 if(Array.isArray(raw.tests))m.tests=raw.tests.filter(t=>t&&typeof t.id==='string'&&/^[a-zA-Z0-9-]{1,80}$/.test(t.id)&&Array.isArray(t.ids)&&t.ids.length<=40&&t.ids.every(id=>MATHS.questions.some(q=>q.id===id))&&t.answers&&typeof t.answers==='object').slice(0,20).map(t=>({id:t.id,level:t.level==='HL'?'HL':'SL',ids:t.ids,finishedAt:Number(t.finishedAt)||Date.now(),answers:Object.fromEntries(t.ids.map(id=>[id,typeof t.answers[id]==='string'?t.answers[id].slice(0,8000):Number.isInteger(t.answers[id])?t.answers[id]:null])),scores:Object.fromEntries(t.ids.map(id=>[id,Math.max(0,Math.min(MATHS.questions.find(q=>q.id===id).marks,Number(t.scores?.[id])||0))]))}));
 // Resume only validated local sessions, never a session imported from cloud/backups.
 if(allowActive&&raw.activeTest&&typeof raw.activeTest.id==='string'&&/^[a-zA-Z0-9-]{1,80}$/.test(raw.activeTest.id)&&Array.isArray(raw.activeTest.ids)&&raw.activeTest.ids.length<=40&&raw.activeTest.ids.every(id=>MATHS.questions.some(q=>q.id===id))&&Number.isFinite(raw.activeTest.deadline)&&raw.activeTest.answers&&typeof raw.activeTest.answers==='object')m.activeTest=raw.activeTest;
 return m;
}
function mathMeaningful(m){return Object.values(m.done||{}).some(Boolean)||Object.keys(m.results||{}).length>0||Object.values(m.drafts||{}).some(Boolean)||(m.tests||[]).length>0||!!m.activeTest;}
function mathLessons(){return MATHS.lessons.filter(l=>progress.maths.level==='HL'||!l.hl);}
function mathQuestions(){return MATHS.questions.filter(q=>progress.maths.level==='HL'||q.level!=='HL');}
function mathTopics(){return MATHS.topics.filter(t=>mathLessons().some(l=>l.topic===t.id));}
function observeCompletion(){
 const marker=$('[data-complete-lesson]');if(!marker||!window.IntersectionObserver)return;
 completionObserver=new IntersectionObserver(entries=>{for(const entry of entries){clearTimeout(completionTimer);if(entry.isIntersecting){completionTimer=setTimeout(()=>{if(document.visibilityState==='hidden'||!document.contains(marker))return;const id=marker.dataset.completeLesson;const maths=id.startsWith('M:');const key=maths?id.slice(2):id;const record=maths?progress.maths.done:progress.done;if(!record[key]){record[key]=true;save();marker.classList.add('revised');marker.textContent='✓ Revised — progress saved';$$('[data-action="done"][data-id="'+key+'"]').forEach(b=>{b.textContent='✓ Revised';b.classList.add('primary')});toast('✓ Revision completed and saved.');}},1200);}}},{threshold:.65});completionObserver.observe(marker);
}
