function mathDiagram(l){
 let svg='',label='';
 const axes='<path d="M45 175H565M60 195V18" stroke="#7c91ad"/><text x="568" y="194" fill="#25446b">x</text><text x="40" y="20" fill="#25446b">y</text>';
 if(l.tool==='binomial'){
  const n=6,p=.5,choose=(n,k)=>{let a=1;for(let i=1;i<=k;i++)a=a*(n-i+1)/i;return a;};
  svg=axes+Array.from({length:n+1},(_,k)=>{const probability=choose(n,k)*p**k*(1-p)**(n-k);return `<rect x="${85+k*65}" y="${175-probability*430}" width="39" height="${probability*430}" fill="#2c65b6"/><text x="${98+k*65}" y="195" fill="#25446b">${k}</text>`}).join('');label='Discrete probabilities for X~B(6,0.5): separate bars for integer outcomes.';
 }else if(l.tool==='normal'){
  const pts=[];for(let x=-3.5;x<=3.5;x+=.04)pts.push(`${300+x*66},${175-140*Math.exp(-x*x/2)}`);svg=axes+`<polyline points="${pts.join(' ')}" fill="none" stroke="#2c65b6" stroke-width="3"/><text x="292" y="195" fill="#25446b">μ</text>`;label='A normal curve: the centre is μ and probabilities are areas, not heights.';
 }else if(l.tool==='matrix'){
  svg='<text x="25" y="65" fill="#25446b" font-size="22">[0.8  0.3]  [100]     [80]</text><text x="25" y="105" fill="#25446b" font-size="22">[0.2  0.7]  [  0]  =  [20]</text><path d="M40 150H530" stroke="#b3c9e5"/><text x="25" y="181" fill="#25446b">Column convention: each column sums to one.</text>';label='A two-state transition model transforms the starting vector (100,0) to (80,20).';
 }else if(l.tool==='network'){
  svg='<path d="M90 165L280 45L490 165L90 165" stroke="#5477a3" stroke-width="3" fill="none"/><g fill="#e2ecfa" stroke="#2c65b6">'+[[90,165,'A'],[280,45,'B'],[490,165,'C']].map(([x,y,t])=>`<circle cx="${x}" cy="${y}" r="24"/><text x="${x-6}" y="${y+5}" fill="#25446b" stroke="none">${t}</text>`).join('')+'</g><g fill="#25446b"><text x="175" y="86">3</text><text x="392" y="90">4</text><text x="280" y="195">10</text></g>';label='A–B–C has total weight 7, compared with direct edge A–C of weight 10.';
 }else if(l.tool==='vector'){
  svg=axes+'<path d="M60 175L390 65L380 84M390 65L368 65" stroke="#2c65b6" stroke-width="4" fill="none"/><path d="M60 175H390V65" stroke="#d16477" stroke-dasharray="5 4" fill="none"/><text x="220" y="195" fill="#25446b">horizontal component</text><text x="405" y="125" fill="#25446b">vertical</text>';label='A vector displacement combines perpendicular horizontal and vertical components.';
 }else if(l.tool==='stats'){
  svg='<path d="M65 165H545M100 95H220M370 95H500M100 68V122M500 68V122" stroke="#52729a" stroke-width="2"/><rect x="220" y="60" width="150" height="70" fill="#dbe9fa" stroke="#2c65b6" stroke-width="2"/><path d="M290 60V130" stroke="#d33a55" stroke-width="3"/><g fill="#25446b"><text x="200" y="153">Q₁</text><text x="270" y="153">Median</text><text x="360" y="153">Q₃</text></g>';label='A box plot shows the median and middle half of the data. Outlier conventions affect whiskers.';
 }else if(l.tool==='probability'){
  svg='<path d="M65 110L250 50M65 110L250 170M250 50L495 25M250 50L495 90M250 170L495 145M250 170L495 205" stroke="#52729a" stroke-width="2"/><g fill="#25446b"><text x="140" y="60">P(A)</text><text x="130" y="165">P(not A)</text><text x="330" y="35">P(B|A)</text><text x="330" y="97">P(not B|A)</text></g>';label='Multiply conditional probabilities along a path; add distinct paths for a total event probability.';
 }else if(l.tool==='geometry'||l.topic[0]==='C'){
  svg='<path d="M100 175H430V40Z" fill="#e2edfa" stroke="#2c65b6" stroke-width="3"/><path d="M410 175V155H430" stroke="#d33a55" fill="none"/><g fill="#25446b"><text x="260" y="199">horizontal length</text><text x="443" y="110">height</text><text x="130" y="163">θ</text></g>';label='Resolve a right triangle into perpendicular horizontal and vertical lengths; use matching units.';
 }else if(l.topic[0]==='A'||l.topic[0]==='E'||l.tool==='finance'||l.tool==='sequence'||l.tool==='regression'){
  let fn=x=>x*.5;
  if(l.topic==='A2'||l.topic[0]==='E')fn=x=>x*x/3-1;
  else if(l.topic==='A4')fn=x=>2*Math.sin(x);
  else if(l.topic==='A3'||l.tool==='finance')fn=x=>Math.exp(x/2)/2;
  const points=[];for(let x=-4;x<=4;x+=.04){const y=fn(x);if(Math.abs(y)<5)points.push(`${300+x*60},${110-y*20}`);}
  svg='<path d="M35 110H570M300 200V15" stroke="#7c91ad"/><text x="570" y="129" fill="#25446b">x</text><text x="312" y="22" fill="#25446b">y</text>'+`<polyline points="${points.join(' ')}" fill="none" stroke="#2c65b6" stroke-width="3"/>`;
  if(l.topic[0]==='E'){svg+='<path d="M180 185L540 65" stroke="#cb3c59" stroke-dasharray="5 4" stroke-width="2"/>';label='Illustration: y=x²/3−1 with tangent y=x−1.75 at x=1.5.';}else label='Illustrative graph for the topic. Use the lesson’s stated function and domain for calculations.';
 }else return '';
 return `<figure class="math-figure"><svg viewBox="0 0 600 220" role="img" aria-label="${esc(label)}"><rect width="600" height="220" fill="#f7faff"/>${svg}</svg><figcaption>${esc(label)}</figcaption></figure>`;
}
function mathLesson(){const l=MATH_LESSON_BY_ID.get(state.id);if(!l)return missing();if(l.hl&&progress.maths.level==='SL')return mathHead('HL extension','Switch the course level to HL to study this topic.');const ls=mathLessons(),i=ls.findIndex(x=>x.id===l.id),v=MATH_DIRECT_VIDEOS[l.id]||MATH_VIDEO_COLLECTIONS[l.topic[0]];return `${mathHead(l.title)}<article class="article maths-article"><div class="row">${pill(l.id)}${pill(l.hl?'HL extension':'SL + HL',l.hl?'hl':'soft')}<button class="btn ${progress.maths.done[l.id]?'primary':''}" data-math-done="${l.id}">${progress.maths.done[l.id]?'✓ Revised':'Mark as revised'}</button><button class="btn" data-math-ask="${l.id}">Ask the tutor</button></div><section class="article-section"><span class="eyebrow">UNDERSTAND THE IDEA</span><h2>What it means and why it works</h2>${l.explanation.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="formula">${esc(l.formula)}</div>${mathDiagram(l)}</section><section class="article-section"><h2>Build your method</h2><ol>${l.method.map(p=>`<li>${esc(p)}</li>`).join('')}</ol><div class="warning"><strong>Before you report an answer</strong>Check units, domain, accuracy and assumptions. Keep unrounded values during the calculation and explain the number in context.</div></section><section class="article-section"><span class="eyebrow">WORKED EXAMPLE</span><h2>${esc(l.worked.question)}</h2><ol>${l.worked.steps.map(p=>`<li>${esc(p)}</li>`).join('')}</ol><div class="answer">✓ ${esc(l.worked.answer)}</div></section><section class="article-section"><span class="eyebrow">YOUR CALCULATOR, STEP BY STEP</span><h2>Calculate with confidence</h2>${calcSteps(l.tool)}</section><section class="article-section"><h2>Watch an explanation</h2><a class="video-card" href="${safeURL(v.url)}" target="_blank" rel="noopener noreferrer"><span class="play">▶</span><div><strong>${esc(v.label)}</strong><p>${MATH_DIRECT_VIDEOS[l.id]?'Direct explanation video':'Video collection — choose the matching lesson title'}</p></div></a><a class="video-card" href="${TI_VIDEOS[progress.maths.calculator]}" target="_blank" rel="noopener noreferrer"><span class="play">▶</span><div><strong>Texas Instruments · calculator walkthrough videos</strong><p>Choose the matching graph, calculation or statistics operation.</p></div></a></section><section class="article-section"><h2>Try it yourself</h2>${mathQuestions().filter(q=>q.lesson===l.id).slice(0,2).map(q=>mathQuestionCard(q)).join('')}</section><div class="completion-marker ${progress.maths.done[l.id]?'revised':''}" data-complete-lesson="M:${l.id}" role="status">${progress.maths.done[l.id]?'✓ Revised — progress saved':'End of revision notes. This lesson will be marked as revised automatically.'}</div><div class="lesson-bottom">${i?`<a class="btn" href="#mathlesson/${ls[i-1].id}">← Previous</a>`:'<span></span>'}<a class="btn" href="#mathtopic/${l.topic}">All lessons</a>${ls[i+1]?`<a class="btn primary" href="#mathlesson/${ls[i+1].id}">Next lesson →</a>`:'<a class="btn primary" href="#mathtest">Build a test →</a>'}</div></article>`;}
function mathQuestionCard(q,test=false){
 const record=progress.maths.results[q.id],a=test?progress.maths.activeTest?.answers[q.id]:record?.choice,checked=!test&&!!record,revealed=!test&&!!mathUI.revealed[q.id];
 return `<article class="card qcard" id="mq-${q.id}"><div class="q-meta">${pill(q.topic)}${pill(q.level==='HL'?'HL':'SL + HL',q.level==='HL'?'hl':'soft')}${pill(q.marks+' marks')}${pill(q.difficulty,'soft')}<span class="qid">${q.id}</span></div><h3>${esc(q.text)}</h3>${q.kind==='mcq'?`<div class="choices">${q.options.map((s,i)=>`<button class="choice ${a===i?'selected':''} ${checked&&a===i?(i===q.correct?'correct':'incorrect'):''}" data-math-choice="${q.id}" data-opt="${i}" data-math-test="${test?'1':'0'}" aria-pressed="${a===i}"><span>${String.fromCharCode(65+i)}</span><span>${esc(s)}</span></button>`).join('')}</div>`:q.kind==='numeric'?`<form class="math-answer-form" data-math-answer="${q.id}" data-math-test="${test?'1':'0'}"><label for="num-${q.id}">Your numerical answer ${q.unit?'('+esc(q.unit)+')':''}</label><div class="row"><input class="numeric-answer ${checked?(record.score===q.marks?'correct':'incorrect'):''}" id="num-${q.id}" name="answer" inputmode="decimal" required value="${esc(test?(a??''):(record?.value??''))}" placeholder="Enter a number (e.g. 3.75)"><button class="btn ${test?'':'primary'}" type="submit">${test?'Save answer':'Check answer'}</button></div></form>`:`<label for="mathdraft-${q.id}">Show your reasoning and calculations</label><textarea id="mathdraft-${q.id}" class="response" data-math-draft="${q.id}" data-math-test="${test?'1':'0'}" maxlength="8000">${esc(test?(a||''):(progress.maths.drafts[q.id]||''))}</textarea>`}${!test?`${checked?`<p role="status" class="answer-status ${record.score===q.marks?'answer-correct':'answer-wrong'}">${record.score===q.marks?'✓ Correct':'✕ Needs revision — reveal the answer below.'}</p>`:''}<button class="btn small" data-math-reveal="${q.id}">${revealed?'Hide answer':'Reveal correct answer'}</button>${revealed?`<div class="solution"><strong>Correct answer</strong>${q.kind==='mcq'?`<p>${String.fromCharCode(65+q.correct)}. ${esc(q.options[q.correct])}</p>`:q.kind==='numeric'?`<p>${q.answer} ${esc(q.unit)}</p>`:''}<ul>${q.scheme.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>${q.kind==='written'?`<label>Self-awarded marks <select data-math-score="${q.id}">${Array.from({length:q.marks+1},(_,i)=>`<option ${record?.score===i?'selected':''}>${i}</option>`).join('')}</select></label><button class="btn small" data-math-selfmark="${q.id}">Save marks</button>`:''}</div>`:''}<button class="text-btn" data-math-question-ask="${q.id}">✦ Explain this question</button>`:'<p class="question-note">Test answer saved locally as you work. Feedback appears after finishing.</p>'}</article>`;
}
function mathBank(){const qs=mathQuestions().filter(q=>(mathUI.topic==='all'||q.topic===mathUI.topic)&&(mathUI.kind==='all'||q.kind===mathUI.kind)&&(mathUI.status==='all'||(mathUI.status==='unanswered'?!progress.maths.results[q.id]:progress.maths.results[q.id]&&progress.maths.results[q.id].score<q.marks)));return `${mathHead('Maths question bank','Original independent practice, not copied IB past-paper questions. Numerical responses mark automatically; extended reasoning is self-marked from the model answer.')}<div class="math-filters"><label>Topic <select data-math-filter="topic"><option value="all">All topics</option>${mathTopics().map(t=>`<option value="${t.id}" ${mathUI.topic===t.id?'selected':''}>${t.id} · ${esc(t.name)}</option>`).join('')}</select></label><label>Style <select data-math-filter="kind">${[['all','All styles'],['mcq','Concept checks'],['numeric','Numerical'],['written','Extended response']].map(([v,t])=>`<option value="${v}" ${mathUI.kind===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Progress <select data-math-filter="status">${[['all','All questions'],['unanswered','Unanswered'],['review','Needs revision']].map(([v,t])=>`<option value="${v}" ${mathUI.status===v?'selected':''}>${t}</option>`).join('')}</select></label></div><p>${qs.length} matching questions · ${progress.maths.level}</p>${qs.slice(0,mathUI.questionLimit).map(q=>mathQuestionCard(q)).join('')}${qs.length>mathUI.questionLimit?'<button class="btn" data-math-more>Load more questions</button>':''}`;}
function mathCalculators(){return `${mathHead('Choose your calculator','Step-by-step instructions for TI-84 Plus CE-T Python Edition or TI-Nspire CX II (non-CAS). Your selection is used throughout the Maths lessons.')}${calcChooser()}<div class="notice">Menus vary between operating-system versions. Refer to the official guide if a label differs. Python is not required for these exam methods. Check your school’s calculator and exam-mode instructions.</div>${Object.keys(CALC_GUIDES).map(k=>`<section class="article-section">${calcSteps(k)}</section>`).join('')}`;}
function mathPapers(){return `${mathHead('Maths papers and exam resources','Choose official IB resources for authentic papers. This site’s question bank and target tests are original practice.')}<div class="notice"><strong>2029 papers are not past papers yet.</strong> The course is first assessed in 2029. Older AI papers are useful only where their topics overlap; their scope and marks differ. The old SL logarithm and trapezoidal-rule topics, and removed HL topics, are not included in this teaching map.</div><div class="paper-grid">${[['Official sample papers','https://www.ibo.org/programmes/diploma-programme/assessment-and-exams/sample-exam-papers/','Select Mathematics: applications and interpretation on IB’s page. Confirm the edition; the currently linked bundle predates 2029.'],['2029 subject brief',MATHS.source,'Read the new course structure and assessment overview.'],['Official IB store','https://www.ibo.org/new-store/','Use the licensed official route for additional examination materials when available.']].map(([title,url,text])=>`<article class="card paper-card"><span class="pill">${progress.maths.level}</span><h2>${title}</h2><p>${text}</p><a class="btn primary" href="${safeURL(url)}" target="_blank" rel="noopener noreferrer">Open official resource ↗</a></article>`).join('')}</div><section class="article-section"><h2>2029 assessment</h2><p>${progress.maths.level==='SL'?'Paper 1 and Paper 2: 1 hour 30 minutes, 75 marks, 40% each.':'Paper 1 and Paper 2: 2 hours, 100 marks, 30% each. Paper 3: 1 hour, 50 marks, 20%.'} Technology is required. The exploration contributes 20%.</p></section>`;}
function mathSkills(){return `${mathHead('Mathematical exploration and exam skills','Practise explaining your model, not just entering numbers.')}<div class="skills-grid">${[['Frame the problem','State a precise question, population or situation. Explain what an answer would help decide.'],['Choose and justify a model','Define variables, units, domain and assumptions. Explain why the method suits the evidence.'],['Communicate the calculation','Show equations, graphs, substitutions and numerical methods. Record the relevant calculator inputs and results.'],['Interpret and evaluate','Return to the original problem. Discuss uncertainty, limitations and how to refine the model.']].map(([title,text])=>`<section class="card skill-card"><h2>${title}</h2><p>${text}</p></section>`).join('')}</div><div class="notice">For the 2029 exploration, IB’s published criteria are Problem specification (4), Abstraction (6), Computation (4) and Interpretation (6). Your teacher confirms the complete requirements.</div>`;}
function mathProgress(){return `${mathHead('Your maths progress','Both subjects are saved in one account document. Signed-in changes use automatic cloud sync; export a backup from the Chemistry progress page if needed.')}${mathStats()}${mathTopicCards()}<div class="row"><button class="btn" data-action="export">Export both subjects</button><button class="btn" data-action="account">Cloud sync status</button></div><h2>Practice history</h2>${progress.maths.tests.map(t=>`<p><a href="#mathresult/${t.id}">${new Date(t.finishedAt).toLocaleDateString()} · ${t.level} · ${t.ids.length} questions →</a></p>`).join('')||'<p>No completed target tests yet.</p>'}`;}
function mathTestBuilder(){const a=progress.maths.activeTest;return `${mathHead('Build a Maths target test','Choose topics, question count and time. These original practice sets do not predict an official IB grade.')}${a?'<div class="notice">You have an unfinished test. <a href="#mathsession">Resume it →</a> <button class="btn small" data-math-discard>Discard</button></div>':''}<form id="mathTestForm" class="card panel"><fieldset><legend>Choose topics</legend><div class="test-topic-grid">${mathTopics().map(t=>`<label><input type="checkbox" name="topic" value="${t.id}" checked> ${t.id} · ${esc(t.name)}</label>`).join('')}</div></fieldset><div class="math-filters"><label>Questions <input type="number" min="1" max="40" name="count" value="10" required></label><label>Minutes <input type="number" min="1" max="180" name="minutes" value="20" required></label><label>Style <select name="kind"><option value="all">Mixed</option><option value="mcq">Concept checks</option><option value="numeric">Numerical</option><option value="written">Extended response</option></select></label></div><button class="btn primary" type="submit">Start target test →</button></form>`;}
function mathSession(){const a=progress.maths.activeTest;if(!a)return mathTestBuilder();return `${mathHead('Your Maths target test','Work through the questions, then finish to see feedback.')}<div class="timebar"><strong id="mathTimer">${timeRemaining(a)}</strong><button class="btn light" data-math-finish>Finish and review →</button></div>${a.ids.map(id=>mathQuestionCard(MATH_QUESTION_BY_ID.get(id),true)).join('')}<button class="btn primary" data-math-finish>Finish and review →</button>`;}
function finishMathTest(){const a=progress.maths.activeTest;if(!a)return;const scores={};for(const id of a.ids){const q=MATH_QUESTION_BY_ID.get(id),v=a.answers[id];if(q.kind==='mcq')scores[id]=v===q.correct?q.marks:0;else if(q.kind==='numeric')scores[id]=numericCorrect(v,q)?q.marks:0;else scores[id]=0;if(q.kind!=='written')progress.maths.results[id]={score:scores[id],at:Date.now(),...(q.kind==='mcq'?{choice:v}:{value:String(v??'')})};}const result={id:a.id,level:a.level,ids:a.ids,answers:a.answers,scores,finishedAt:Date.now()};progress.maths.tests.unshift(result);progress.maths.tests=progress.maths.tests.slice(0,20);progress.maths.activeTest=null;save();location.hash='mathresult/'+result.id;}
function numericCorrect(v,q){if(typeof v!=='string'||!v.trim()||!/^[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?$/.test(v.trim()))return false;return Math.abs(Number(v)-q.answer)<=q.tolerance;}
function mathResult(){const t=progress.maths.tests.find(t=>t.id===state.id);if(!t)return missing();const max=t.ids.reduce((n,id)=>n+MATH_QUESTION_BY_ID.get(id).marks,0),got=Object.values(t.scores).reduce((a,b)=>a+b,0),written=t.ids.some(id=>MATH_QUESTION_BY_ID.get(id).kind==='written');return `${mathHead('Review your Maths test',got+' / '+max+' marks'+(written?' · provisional until extended responses are self-marked':''))}${t.ids.map(id=>{const q=MATH_QUESTION_BY_ID.get(id);return `<section class="card qcard"><h2>${esc(q.text)}</h2><p class="answer-status ${t.scores[id]===q.marks?'answer-correct':'answer-wrong'}">Your answer: ${esc(q.kind==='mcq'?q.options[t.answers[id]]||'Unanswered':t.answers[id]||'Unanswered')}</p><details class="solution"><summary>Reveal correct answer</summary>${q.kind==='mcq'?`<p>${esc(q.options[q.correct])}</p>`:q.kind==='numeric'?`<p>${q.answer} ${esc(q.unit)}</p>`:''}<ul>${q.scheme.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>${q.kind==='written'?`<label>Self-awarded marks <select data-math-test-score="${t.id}" data-q="${id}">${Array.from({length:q.marks+1},(_,i)=>`<option ${t.scores[id]===i?'selected':''}>${i}</option>`).join('')}</select></label>`:''}</details></section>`}).join('')}<a class="btn primary" href="#mathtest">Build another test →</a>`;}
function mathSearch(){const q=state.search.toLowerCase();return `${mathHead('Find a Maths concept')}<div class="lessons">${mathLessons().filter(l=>[l.title,l.formula,...l.explanation].join(' ').toLowerCase().includes(q)).map(l=>`<a class="lesson-link" href="#mathlesson/${l.id}"><strong>${esc(l.title)}</strong></a>`).join('')||'<p>No matching lesson found.</p>'}</div>`;}
function mathsRender(){const routes={maths:mathOverview,mathnotes:mathNotes,mathtopic:mathTopic,mathlesson:mathLesson,mathbank:mathBank,mathcalc:mathCalculators,mathpapers:mathPapers,mathskills:mathSkills,mathprogress:mathProgress,mathtest:mathTestBuilder,mathsession:mathSession,mathresult:mathResult,mathsearch:mathSearch};return (routes[state.page]||mathOverview)();}
function handleMathsClick(e){
 const course=e.target.closest('[data-course]');if(course){if(course.dataset.course==='maths')progress.maths.level=course.dataset.courseLevel;else progress.level=course.dataset.courseLevel;save();return false;}
 const done=e.target.closest('[data-math-done]');if(done){const id=done.dataset.mathDone;progress.maths.done[id]=!progress.maths.done[id];save();rerender();return true;}
 const choice=e.target.closest('[data-math-choice]');if(choice){const q=MATH_QUESTION_BY_ID.get(choice.dataset.mathChoice);if(!q)return true;const v=Number(choice.dataset.opt);if(choice.dataset.mathTest==='1'){if(progress.maths.activeTest){progress.maths.activeTest.answers[q.id]=v;save();}}else{progress.maths.results[q.id]={score:v===q.correct?q.marks:0,choice:v,at:Date.now()};mathUI.revealed[q.id]=false;save();}rerender();return true;}
 const reveal=e.target.closest('[data-math-reveal]');if(reveal){mathUI.revealed[reveal.dataset.mathReveal]=!mathUI.revealed[reveal.dataset.mathReveal];rerender();return true;}
 const self=e.target.closest('[data-math-selfmark]');if(self){const q=MATH_QUESTION_BY_ID.get(self.dataset.mathSelfmark);progress.maths.results[q.id]={score:Number($('[data-math-score="'+q.id+'"]').value),at:Date.now()};save();rerender();return true;}
 const ask=e.target.closest('[data-math-ask]');if(ask){openMathTutor(ask.dataset.mathAsk);return true;}
 const aq=e.target.closest('[data-math-question-ask]');if(aq){const q=MATH_QUESTION_BY_ID.get(aq.dataset.mathQuestionAsk);state.messages=[];openTutor('Subject: Mathematics AI '+progress.maths.level+'; first assessment 2029. Calculator: '+progress.maths.calculator+'\nQuestion: '+q.text+'\nOriginal answer guidance: '+q.scheme.join('\n'),'Maths · '+q.id);return true;}
 if(e.target.closest('[data-math-more]')){mathUI.questionLimit+=18;rerender();return true;}
 if(e.target.closest('[data-math-discard]')){if(confirm('Discard this Maths test?')){progress.maths.activeTest=null;save();rerender();}return true;}
 if(e.target.closest('[data-math-finish]')){if(confirm('Finish and review this Maths test?'))finishMathTest();return true;}
 return false;
}
function handleMathsChange(e){
 if(e.target.id==='examSession'){const value=e.target.value;$('#examSessionNote').textContent=value+' · exact subject and paper dates awaiting verification in IB’s published timetable. Open the official source for the latest schedule.';return true;}
 if(e.target.id==='level'&&state.page.startsWith('math')){if(progress.maths.activeTest){e.target.value=progress.maths.level;toast('Finish or discard the Maths test before switching level.');return true;}progress.maths.level=e.target.value;mathUI.topic='all';save();rerender();return true;}
 if(e.target.matches('[data-math-calculator]')){progress.maths.calculator=e.target.value==='nspire'?'nspire':'ti84';save();rerender();return true;}
 if(e.target.dataset.mathFilter){mathUI[e.target.dataset.mathFilter]=e.target.value;mathUI.questionLimit=18;rerender();return true;}
 if(e.target.dataset.mathTestScore){const t=progress.maths.tests.find(t=>t.id===e.target.dataset.mathTestScore),q=MATH_QUESTION_BY_ID.get(e.target.dataset.q);t.scores[q.id]=Number(e.target.value);progress.maths.results[q.id]={score:t.scores[q.id],at:Date.now()};save();rerender();return true;}
 return false;
}
function handleMathsSubmit(e){
 if(e.target.dataset.mathAnswer){e.preventDefault();const q=MATH_QUESTION_BY_ID.get(e.target.dataset.mathAnswer),value=new FormData(e.target).get('answer').trim();if(!value)return true;if(e.target.dataset.mathTest==='1'){if(progress.maths.activeTest)progress.maths.activeTest.answers[q.id]=value;}else{progress.maths.results[q.id]={score:numericCorrect(value,q)?q.marks:0,value,at:Date.now()};mathUI.revealed[q.id]=false;}save();rerender();return true;}
 if(e.target.id==='mathTestForm'){e.preventDefault();if(progress.maths.activeTest){toast('Finish or discard the current Maths test first.');return true;}const f=new FormData(e.target),ts=f.getAll('topic'),pool=mathQuestions().filter(q=>ts.includes(q.topic)&&(f.get('kind')==='all'||f.get('kind')===q.kind));if(!pool.length){toast('Choose at least one topic containing the selected question style.');return true;}const count=Math.min(40,Math.max(1,Number(f.get('count')))),minutes=Math.min(180,Math.max(1,Number(f.get('minutes'))));progress.maths.activeTest={id:crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2),level:progress.maths.level,ids:shuffled(pool).slice(0,count).map(q=>q.id),answers:{},deadline:Date.now()+minutes*60000,startedAt:Date.now()};save();location.hash='mathsession';return true;}return false;
}
function handleMathsInput(e){if(e.target.dataset.mathDraft){const id=e.target.dataset.mathDraft,v=e.target.value.slice(0,8000);if(e.target.dataset.mathTest==='1'&&progress.maths.activeTest)progress.maths.activeTest.answers[id]=v;else progress.maths.drafts[id]=v;save();return true;}if(e.target.closest('.math-answer-form')&&e.target.closest('.math-answer-form').dataset.mathTest==='1'&&progress.maths.activeTest){progress.maths.activeTest.answers[e.target.closest('form').dataset.mathAnswer]=e.target.value.slice(0,100);save();return true;}return false;}
function tickMathsTest(){const a=progress.maths.activeTest;if(a){if(Date.now()>=a.deadline){finishMathTest();toast('Maths test time finished. Answers saved for review.');}else if($('#mathTimer'))$('#mathTimer').textContent=timeRemaining(a);}}
function openMathTutor(id=state.id){const l=MATH_LESSON_BY_ID.get(id);state.messages=[];openTutor('Subject: Mathematics applications and interpretation '+progress.maths.level+'; first assessment 2029. Calculator: '+(progress.maths.calculator==='ti84'?'TI-84 Plus CE-T Python Edition':'TI-Nspire CX II non-CAS')+'\n'+(l?[l.title,l.formula,...l.explanation,...l.worked.steps].join('\n'):''),'Mathematics AI '+progress.maths.level+(l?' · '+l.title:''));}

init();
